 PRAGMA foreign_keys = ON;                                                                                                                                                                                                                    
                                                                                                                                                                                                                                              
 -- Raw HTML web pages                                                                                                                                                                                                                        
 CREATE TABLE IF NOT EXISTS web_pages (                                                                                                                                                                                                       
     id          INTEGER PRIMARY KEY AUTOINCREMENT,                                                                                                                                                                                           
     url         TEXT UNIQUE NOT NULL,                                                                                                                                                                                                        
     html        TEXT NOT NULL,                                                                                                                                                                                                               
     fetched_at  DATETIME DEFAULT CURRENT_TIMESTAMP                                                                                                                                                                                           
 );                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                              
 -- Individual JSON-LD tags extracted from each page                                                                                                                                                                                          
 CREATE TABLE IF NOT EXISTS ldjson_payloads (                                                                                                                                                                                                 
     id           INTEGER PRIMARY KEY AUTOINCREMENT,                                                                                                                                                                                          
     page_id      INTEGER NOT NULL REFERENCES web_pages(id) ON DELETE CASCADE,                                                                                                                                                                
     tag_index    INTEGER NOT NULL,                                                                                                                                                                                                           
     raw_content  TEXT NOT NULL CHECK(json_valid(raw_content)),                                                                                                                                                                               
     created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,                                                                                                                                                                                         
     UNIQUE(page_id, tag_index)                                                                                                                                                                                                               
 );                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                              
 CREATE INDEX IF NOT EXISTS idx_ldjson_page_id ON ldjson_payloads(page_id);